import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch80Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("sm3_en_128");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static ServerMatch fixture(AttackDefinition attack,AbilityDefinition ability){return NonPokemonBatch78Test.fixture(IDS.getFirst(),attack,true,ability,false);}
    static CardInstance equip(ServerMatch m,UUID p,UUID host){var card=hand(m,p,"trainer");m.attachToolByEffect(m.currentPlayer(),p,EffectSourceZone.HAND,card.instanceId(),p,host);return card;}
    static List<CardInstance> energy(ServerMatch m,UUID p,UUID host,int count){var result=new ArrayList<CardInstance>();for(int i=0;i<count;i++)result.add(NonPokemonBatch78Test.energy(m,p,i%2==0?p:other(p),host,"energy"));return result;}
    static ServerMatch aiGame(String id){var m=fixture(GeneratedRuleBatch8Test.hit(300,false),null);for(UUID p:List.of(A,B))energy(m,p,active(m,p),3);return m;}
    static void choose(ServerMatch m,UUID p,List<CardInstance> cards,UUID target){var q=m.effectCardPrompt(p);m.submitEffectCards(p,q.resolutionId(),q.step(),cards.stream().map(CardInstance::instanceId).toList());if(!cards.isEmpty()){var t=m.effectAttachmentPrompt(p);m.chooseEffectAttachmentTarget(p,t.resolutionId(),t.step(),target);}}
    static void strike(ServerMatch m,UUID p,UUID host){NonPokemonBatch75Test.hurt(m,p,host,950);m.endTurn(p);m.attack(other(p),"hit");}
    public static void main(String[] args){amounts();authority();causes();multiple();forcedSwitch();System.out.println("NonPokemonBatch80Test passed: both owners, 1..3 of up to4 available Basic Energy before KO disposal, one own Bench, Special exclusion, foreign physical owners, atomic wrong/stale choice rejection, attack cause and Tool suppression/removal, no-Bench completion, shared pool across two Batons and captured Active-before-switch timing");}
    static void amounts(){for(UUID p:List.of(A,B))for(int available=0;available<=4;available++)for(int count=available==0?0:1;count<=Math.min(3,available);count++){
        var m=fixture(GeneratedRuleBatch8Test.hit(100,false),null);if(p.equals(B))m.endTurn(A);UUID source=active(m,p),target=bench(m,p),opp=other(p);var tool=equip(m,p,source);var cards=energy(m,p,source,available);var special=NonPokemonBatch78Test.energy(m,p,p,source,"special");var rng=m.randomTranscript();strike(m,p,source);if(available>0){var q=m.effectCardPrompt(p);check(q.minimum()==1&&q.maximum()==Math.min(3,available)&&new HashSet<>(q.candidates()).equals(new HashSet<>(cards)),"Baton used Energy units, Special Energy or wrong count");check(active(m,p).equals(source)&&m.privateView(opp).prizes().size()==6,"KO disposed source before Energy selection");choose(m,p,cards.subList(0,count),target);}check(m.privateView(p).discard().contains(tool)&&m.privateView(p).discard().contains(special),"Baton rescued own Tool or Special Energy");var selected=cards.subList(0,count);check(new HashSet<>(EventTargetBindingTest.field(m).pokemonView(p,target).attachedEnergyIds()).equals(new HashSet<>(selected.stream().map(CardInstance::instanceId).toList())),"Baton did not move all selected cards to one host");for(var card:cards)check(m.privateView(card.ownerId()).discard().contains(card)==!selected.contains(card),"Baton lost a card or ignored its physical owner");check(m.randomTranscript().equals(rng),"Baton unexpectedly shuffled");NonPokemonBatch67Test.settle(m);check(m.privateView(opp).prizes().size()==5,"Baton canceled or duplicated a Prize");
    }}
    static void authority(){var m=fixture(GeneratedRuleBatch8Test.hit(100,false),null);UUID source=active(m,A),target=bench(m,A);equip(m,A,source);var cards=energy(m,A,source,4);var special=NonPokemonBatch78Test.energy(m,A,A,source,"special");strike(m,A,source);var q=m.effectCardPrompt(A);var selected=cards.subList(0,3).stream().map(CardInstance::instanceId).toList();GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(A,q.resolutionId(),q.step(),List.of()));GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(B,q.resolutionId(),q.step(),selected));GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(A,q.resolutionId(),q.step(),cards.stream().map(CardInstance::instanceId).toList()));GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(special.instanceId())));m.submitEffectCards(A,q.resolutionId(),q.step(),selected);var t=m.effectAttachmentPrompt(A);GeneratedRuleBatch8Test.reject(()->m.chooseEffectAttachmentTarget(B,t.resolutionId(),t.step(),target));GeneratedRuleBatch8Test.reject(()->m.chooseEffectAttachmentTarget(A,t.resolutionId(),t.step(),source));GeneratedRuleBatch8Test.reject(()->m.chooseEffectAttachmentTarget(A,t.resolutionId(),t.step(),bench(m,B)));check(m.activePokemonView(A).attachedEnergyIds().size()==5,"Rejected target partially moved Energy");m.chooseEffectAttachmentTarget(A,t.resolutionId(),t.step(),target);GeneratedRuleBatch8Test.reject(()->m.chooseEffectAttachmentTarget(A,t.resolutionId(),t.step(),target));GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(A,q.resolutionId(),q.step(),selected));NonPokemonBatch67Test.settle(m);}
    static void causes(){for(String mode:List.of("bench","disabled","removed","counter","direct","checkup","recoil","empty")){
        var attack=mode.equals("counter")?DeckDiscardTriggeredAbilityTest.attack(0,"{\"type\":\"damage_counter\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":2}"):mode.equals("recoil")?DamageTriggeredAbilityTest.attack(0,",\"selfDamage\":100"):GeneratedRuleBatch8Test.hit(100,mode.equals("bench"));var m=fixture(attack,null);UUID host=mode.equals("bench")?bench(m,A):active(m,A);var tool=equip(m,A,host);var cards=energy(m,A,host,3);if(mode.equals("disabled"))m.disableToolEffectsByEffect(A,A,host);if(mode.equals("removed"))m.discardToolByEffect(A,A,host,tool.instanceId());if(mode.equals("empty"))m.movePokemonByEffect(A,A,bench(m,A),LeavePlayDestination.HAND);NonPokemonBatch75Test.hurt(m,A,host,mode.equals("counter")?980:mode.equals("checkup")?990:950);if(mode.equals("direct"))m.knockOutPokemonByEffect(A,A,host);else if(mode.equals("checkup")){m.applySpecialConditionByEffect(A,A,SpecialCondition.POISONED);m.endTurn(A);}else if(mode.equals("recoil"))m.attack(A,"hit");else{m.endTurn(A);m.attack(B,"hit");}check(!m.hasPendingCardSelection()&&!m.hasPendingAttachmentTarget(),"Baton incorrectly triggered: "+mode);NonPokemonBatch67Test.settle(m);for(var card:cards)check(m.privateView(card.ownerId()).discard().contains(card),"Baton rescued Energy on invalid cause: "+mode);
    }}
    static void multiple(){var m=fixture(GeneratedRuleBatch8Test.hit(100,false),NonPokemonBatch74Test.passive("{\"type\":\"tool_capacity\",\"target\":\"SELF\",\"amount\":2}"));UUID source=active(m,A),target=bench(m,A);equip(m,A,source);equip(m,A,source);var cards=energy(m,A,source,4);strike(m,A,source);var order=m.triggerOrderPrompt();check(order!=null&&order.entries().size()==2,"Two Batons did not enter shared KO ordering");m.chooseTriggeredEffect(A,order.id(),order.entries().getFirst().id());choose(m,A,cards.subList(0,3),target);NonPokemonBatch79Test.triggerOrder(m);var q=m.effectCardPrompt(A);check(q.candidates().equals(List.of(cards.getLast()))&&q.maximum()==1,"Second Baton reused already transferred Energy");choose(m,A,List.of(cards.getLast()),target);NonPokemonBatch67Test.settle(m);check(m.activePokemonView(A).attachedEnergyIds().size()==4,"Two Batons failed to preserve four physical Energy");}
    static void forcedSwitch(){var attack=DeckDiscardTriggeredAbilityTest.attack(100,"{\"type\":\"force_switch\",\"target\":\"SELECT_OPPONENT_POKEMON\"}");var m=fixture(attack,null);m.playBasicPokemonToBench(A,hand(m,A,"basic").instanceId());UUID source=active(m,A),replacement=bench(m,A),target=m.benchPokemonView(A).getLast().pokemonId();equip(m,A,source);var cards=energy(m,A,source,2);strike(m,A,source);var q=m.effectPokemonPrompt(A);m.chooseEffectPokemon(A,q.resolutionId(),q.step(),replacement);check(m.hasPendingCardSelection(),"Damage-time Active identity lost after forced switch");choose(m,A,cards,target);NonPokemonBatch67Test.settle(m);check(active(m,A).equals(replacement)&&m.benchPokemonView(A).getFirst().attachedEnergyIds().size()==2,"Baton chose new Active or lost target after switch");}
}
